test('invoiceTotals: multiple lines with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
      { qty: 20, unitPrice: 500, discountPercent: 0, vatRate: 9 },
      { qty: 5, unitPrice: 2000, discountPercent: 10, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);

  const line1Subtotal = 10000;
  const line1Discount = 500;
  const line1VAT = Math.round((line1Subtotal - line1Discount) * (21 / 100));

  const line2Subtotal = 10000;
  const line2VAT = Math.round(line2Subtotal * (9 / 100));

  const line3Subtotal = 10000;
  const line3Discount = 1000;
  const line3VAT = 0;

  const expectedSubtotal = 30000;
  const expectedDiscount = 1500;
  const expectedVAT = line1VAT + line2VAT + line3VAT;
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVAT;

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedTotal);
});
